<?php $c=$campaign;$pct=$c['target_amount']>0?min(100,round($c['raised']/$c['target_amount']*100)):0; ?>
<section class="campaign-detail-hero"><div class="container detail-grid"><div class="detail-photo reveal"><img src="<?=e($c['cover_image']?public_upload($c['cover_image']):asset('images/demo/campaign-families.jpg'))?>" alt="<?=e($c['title'])?>"></div><div class="detail-copy reveal"><span class="eyebrow green-text"><?=e($c['category']?:'FUNDRAISING CAMPAIGN')?></span><h1><?=e($c['title'])?></h1><p><?=e($c['short_description']??'')?></p><div class="campaign-progress-large"><div><span>Verified raised</span><b><?=money($c['raised'],$c['currency'])?></b></div><div class="progress"><i style="width:<?=$pct?>%"></i></div><div><span><?=$pct?>% funded</span><span>Goal <?=money($c['target_amount'],$c['currency'])?></span></div></div><?php if(!empty($campaignOpen)):?><a class="btn btn-primary btn-large" href="<?=url('donate?campaign='.$c['id'])?>">♡ Donate to this Campaign</a><?php elseif(!($fundraisingOn??true)):?><div class="fundraising-paused7" role="status"><?=site_line_icon('heart')?><div><b>Donations to this campaign are paused</b><p><?=e($pausedMessage??'')?></p></div></div><?php endif;?><?=share_bar(absolute_url('campaigns/'.$c['slug']),$c['title'],$c['short_description']??'','campaign')?></div></div></section>
<section class="section"><div class="container detail-body"><article class="content-glass reveal"><h2>Campaign Story</h2><div class="prose"><?=nl2br(e($c['description']?:$c['short_description']))?></div></article><aside class="detail-side glass-panel reveal"><h3>Campaign Information</h3><p><b>Status</b><span><?=e(ucfirst($c['status']))?></span></p><p><b>Location</b><span><?=e($c['location']?:'Not specified')?></span></p><p><b>Start Date</b><span><?=e($c['start_date']?:'Not specified')?></span></p><p><b>End Date</b><span><?=e($c['end_date']?:'Open')?></span></p></aside></div></section>
